#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — Track Garantías: dependencias + backend Supabase + Edge Function
# mfa-enviar-codigo (MFA por email) + validación del login en dos pasos.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=10
ENV_FILE="frontend/.env"
PROJECT_REF=""
FUNCTION_URL=""

banner "Track Garantías — Supabase + Edge Function MFA"

# ── 1. Prerrequisitos ──────────────────────────────────────────────────────
stage "Prerrequisitos"
say "Comprobando las herramientas que necesita este flujo."
for tool in node npm git supabase curl; do
  if command -v "$tool" >/dev/null 2>&1; then
    printf '  %s✓%s %s → %s\n' "$GREEN" "$RESET" "$tool" "$("$tool" --version 2>&1 | head -n1)"
  else
    warn "$tool no está instalado."
    case "$tool" in
      supabase) open_url "https://supabase.com/docs/guides/cli/getting-started" ;;
      node|npm) open_url "https://nodejs.org/" ;;
    esac
    SKIPPED+=("instalar $tool antes de continuar")
  fi
done
if ((${#SKIPPED[@]})); then
  warn "Instala lo que falte y vuelve a correr este script."
  pause "Presiona Enter cuando ya lo tengas listo (o Ctrl-C para salir)"
fi

# ── 2. Instalar dependencias ───────────────────────────────────────────────
stage "Instalar dependencias del frontend"
say "El proyecto no tiene dependencias en la raíz; todo vive en frontend/."
if confirm "¿Correr 'npm install' en frontend/ ahora?"; then
  (cd frontend && npm install)
  printf '  %s✓ listo%s\n' "$GREEN" "$RESET"
else
  SKIPPED+=("npm install en frontend/")
fi

# ── 3. Login en Supabase CLI ───────────────────────────────────────────────
stage "Iniciar sesión en Supabase CLI"
say "Necesitas un access token personal (no el de un proyecto)."
open_url "https://supabase.com/dashboard/account/tokens"
step "Genera un token (o reutiliza uno) y cópialo."
ask_secret SUPABASE_ACCESS_TOKEN "Pega el access token:"
if [[ -n "$SUPABASE_ACCESS_TOKEN" ]]; then
  supabase login --token "$SUPABASE_ACCESS_TOKEN"
else
  warn "sin token, 'supabase login' interactivo se abrirá en el navegador."
  supabase login
fi

# ── 4. Vincular el proyecto ────────────────────────────────────────────────
stage "Vincular el proyecto Supabase"
say "El project-ref aparece en la URL del dashboard: https://<project-ref>.supabase.co"
open_url "https://supabase.com/dashboard/projects"
step "Entra al proyecto correcto y copia su project-ref (Settings → General)."
ask PROJECT_REF "Pega el project-ref:"
if [[ ! -f supabase/config.toml ]]; then
  note "no hay supabase/config.toml todavía — inicializando el proyecto local."
  supabase init
fi
supabase link --project-ref "$PROJECT_REF"
write_env VITE_SUPABASE_PROJECT_REF "$PROJECT_REF"

# ── 5. Configurar frontend/.env ────────────────────────────────────────────
stage "Configurar frontend/.env"
say "El cliente de Supabase del frontend (frontend/src/lib/supabaseClient.js) lee estas dos variables."
open_url "https://supabase.com/dashboard/project/${PROJECT_REF}/settings/api"
step "Copia la 'Project URL'."
ask VITE_SUPABASE_URL "Pega VITE_SUPABASE_URL:"
step "Copia la 'anon public' key. NUNCA la 'service_role'."
ask VITE_SUPABASE_ANON_KEY "Pega VITE_SUPABASE_ANON_KEY:"
write_env VITE_SUPABASE_URL "$VITE_SUPABASE_URL"
write_env VITE_SUPABASE_ANON_KEY "$VITE_SUPABASE_ANON_KEY"

# ── 6. Secrets del backend (Resend + CORS) ─────────────────────────────────
stage "Configurar secrets de la Edge Function"
say "mfa-enviar-codigo necesita RESEND_API_KEY y ORIGENES_PERMITIDOS."
open_url "https://resend.com/api-keys"
step "Crea o copia una API key de Resend."
ask_secret RESEND_API_KEY "Pega RESEND_API_KEY:"
ask ORIGENES_PERMITIDOS "Orígenes permitidos, separados por coma [http://localhost:5173]:"
ORIGENES_PERMITIDOS="${ORIGENES_PERMITIDOS:-http://localhost:5173}"
if [[ -n "$RESEND_API_KEY" ]]; then
  supabase secrets set "RESEND_API_KEY=${RESEND_API_KEY}"
  WRITTEN_SECRET+=("RESEND_API_KEY (Supabase)")
fi
supabase secrets set "ORIGENES_PERMITIDOS=${ORIGENES_PERMITIDOS}"
WRITTEN_SECRET+=("ORIGENES_PERMITIDOS (Supabase)")
note "SUPABASE_URL / SUPABASE_ANON_KEY / SUPABASE_SERVICE_ROLE_KEY los inyecta la plataforma; no hace falta fijarlos."

# ── 7. Migraciones remotas ─────────────────────────────────────────────────
stage "Aplicar migraciones a la base remota"
say "email_mfa_codes y generate_mfa_code() (migración 20260907000003_mfa_email.sql) deben existir en la base remota antes de desplegar la función."
if confirm "¿Correr 'supabase db push' contra el proyecto vinculado ahora? (acción sobre la BD remota)"; then
  supabase db push
else
  SKIPPED+=("supabase db push — la función fallará sin la tabla email_mfa_codes")
fi

# ── 8. Desplegar la Edge Function ──────────────────────────────────────────
stage "Desplegar mfa-enviar-codigo"
say "verify_jwt queda activado por defecto: la función exigirá un JWT válido."
supabase functions deploy mfa-enviar-codigo
FUNCTION_URL="https://${PROJECT_REF}.supabase.co/functions/v1/mfa-enviar-codigo"
note "URL de la función: $FUNCTION_URL"

# ── 9. Validar seguridad básica sin JWT ────────────────────────────────────
stage "Validar la función sin JWT"
say "Debe responder 401/sin autorización — nunca 200."
HTTP_CODE=$(curl -s -o /dev/null -w '%{http_code}' -X POST "$FUNCTION_URL" \
  -H "Content-Type: application/json" \
  -H "Origin: ${ORIGENES_PERMITIDOS%%,*}") || HTTP_CODE="error"
if [[ "$HTTP_CODE" == "401" ]]; then
  printf '  %s✓ correcto%s: respondió 401 sin JWT\n' "$GREEN" "$RESET"
else
  warn "respondió '$HTTP_CODE' en vez de 401 — revisa 'supabase functions logs mfa-enviar-codigo --since 1h'"
fi

# ── 10. Probar el flujo completo: login + MFA por correo ───────────────────
stage "Probar login + segundo factor en la app"
say "Arranca el frontend en OTRA terminal (este script no debe bloquearse):"
step "cd frontend && npm run dev"
open_url "http://localhost:5173"
say "En el navegador:"
step "1. Inicia sesión con un usuario real (email + contraseña)."
step "2. La app debe llamar a mfa-enviar-codigo e invitarte a introducir un código."
step "3. Revisa el correo (con el sandbox de Resend, solo llega a la cuenta con la que creaste Resend)."
step "4. Introduce el código; debe conceder acceso. Un código incorrecto o vencido debe rechazarse."
if confirm "¿El login + MFA funcionó de punta a punta?"; then
  printf '  %s✓ flujo validado%s\n' "$GREEN" "$RESET"
else
  SKIPPED+=("flujo de login + MFA no validado — revisa 'supabase functions logs mfa-enviar-codigo --since 1h'")
fi

finish
